```js
export function parse(text, { delimiter = "," } = {}) {
  const records = [];
  let record = [];
  let field = "";
  let inQuotes = false;
  let wasQuoted = false;
  let line = 1;
  let fieldStartLine = 1;
  let i = 0;

  const endField = () => {
    record.push(field);
    field = "";
    wasQuoted = false;
  };
  const endRecord = () => {
    endField();
    records.push(record);
    record = [];
  };

  while (i < text.length) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          inQuotes = false;
          i++;
        }
      } else {
        if (c === "\n") line++;
        field += c;
        i++;
      }
      continue;
    }
    if (c === '"' && field === "" && !wasQuoted) {
      inQuotes = true;
      wasQuoted = true;
      fieldStartLine = line;
      i++;
    } else if (c === "\n") {
      endRecord();
      line++;
      i++;
    } else if (c === "\r") {
      if (text[i + 1] === "\n") i++;
      endRecord();
      line++;
      i++;
    } else if (c === delimiter) {
      endField();
      i++;
    } else {
      field += c;
      i++;
    }
  }
  if (inQuotes) throw new CsvError("unterminated quoted field", fieldStartLine);
  if (field !== "" || wasQuoted || record.length > 0) endRecord();
  return records;
}
```

