```js
// RFC 4180 CSV parser. Fields are separated by `delimiter`, records by CRLF or LF. A field may be quoted with `"`;
// inside quotes, delimiters and line breaks are literal and `""` is an escaped quote. A quote inside an unquoted field
// is literal. A trailing line break at the end of the input does not start a new record. An unterminated quoted
// field is an error reported at the line where the field starts.

export class CsvError extends Error {
  constructor(message, line) {
    super(`${message} (line ${line})`);
    this.line = line;
  }
}

export function parse(text, { delimiter = "," } = {}) {
  const records = [];
  let record = [];
  let field = "";
  let inQuotes = false;
  let wasQuoted = false;
  let line = 1;
  let fieldStartLine = 1;
  let i = 0;

  const endField = () => {
    record.push(field);
    field = "";
    wasQuoted = false;
  };
  const endRecord = () => {
    endField();
    records.push(record);
    record = [];
  };

  while (i < text.length) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          // `""` inside a quoted field is an escaped quote.
          field += '"';
          i += 2;
        } else {
          inQuotes = false;
          i++;
        }
      } else {
        if (c === "\n") line++;
        field += c;
        i++;
      }
      continue;
    }
    if (c === '"' && field === "" && !wasQuoted) {
      inQuotes = true;
      wasQuoted = true;
      fieldStartLine = line;
      i++;
    } else if (c === "\r") {
      // CRLF is a single record separator; a lone CR is literal.
      if (text[i + 1] === "\n") i++;
      endRecord();
      line++;
      i++;
    } else if (c === "\n") {
      endRecord();
      line++;
      i++;
    } else if (c === delimiter) {
      endField();
      i++;
    } else {
      field += c;
      i++;
    }
  }
  if (inQuotes) throw new CsvError("unterminated quoted field", fieldStartLine);
  if (field !== "" || wasQuoted || record.length > 0) endRecord();
  return records;
}
```

